// Helper function to clean and parse a single content string
function cleanAndParseContent(content) {
  // Step 1: Fix common invalid JSON issues BEFORE parsing (non-string related)
  // Remove commas from numbers (e.g., 53,100 -> 53100)
  content = content.replace(/(\d+),(\d+)/g, '$1$2');

  // Fix invalid pe_ratio like "- (loss-making)" or "-" -> null
  content = content.replace(/"pe_ratio":\s*-\s*\(loss-making\)/g, '"pe_ratio": null');
  content = content.replace(/"pe_ratio":\s*-\s*/g, '"pe_ratio": null');

  // Remove trailing commas in objects/arrays (common AI output error)
  content = content.replace(/,\s*(?=}|[}\]])/g, '');

  // Fix underscores in numbers (e.g., 1_230 -> 1230)
  content = content.replace(/(\d+)_(\d+)/g, '$1$2');

  // Debug log: Show pre-parse cleaned content
  console.log('Pre-parse cleaned content (first 200 chars):', content.substring(0, 200));

  // Step 2: Parse the cleaned string as JSON (\\n is still escaped here)
  try {
    const parsed = JSON.parse(content);

    // Step 3: Post-parse: Replace escaped \\n with actual \n in specific string fields for readability
    if (typeof parsed.quantitative_data === 'string') {
      parsed.quantitative_data = parsed.quantitative_data.replace(/\\n/g, '\n');
      // Optionally flatten to single-line (uncomment if preferred):
      // parsed.quantitative_data = parsed.quantitative_data.replace(/\\n/g, '; ');
    }
    if (typeof parsed.industry_drivers === 'string') {
      parsed.industry_drivers = parsed.industry_drivers.replace(/\\n/g, '\n');
      // Optionally flatten:
      // parsed.industry_drivers = parsed.industry_drivers.replace(/\\n/g, '; ');
    }

    // Step 4: Other post-parse cleaning
    // Stringify peer_group_list for Sheets
    if (parsed.peer_group_list && Array.isArray(parsed.peer_group_list)) {
      parsed.peer_group_list = parsed.peer_group_list.map(peer => 
        `${peer.peer_name}: ${peer.comparison_reason} (P/E: ${peer.pe_ratio ?? 'N/A'})`
      ).join('; ');
    }
    // Convert target_price to a single bullet-point string
    if (parsed.target_price) {
      parsed.target_price = 
        `- Target INR: ${parsed.target_price.target_inr}\n` +
        `- Upside/Downside %: ${parsed.target_price.upside_downside_percent}\n` +
        `- Range Low INR: ${parsed.target_price.range_low_inr}\n` +
        `- Range High INR: ${parsed.target_price.range_high_inr}\n` +
        `- Methodology: ${parsed.target_price.methodology}`;
      // No delete needed since we're overwriting the key with a string
    }

    // Debug log: Successful parse
    console.log('Successfully parsed content.');

    return parsed;
  } catch (error) {
    console.error('Error parsing content:', error.message);
    console.error('Error position in content:', content.substring(error.columnNumber - 50, error.columnNumber + 50)); // Approximate error spot
    console.error('Problematic content snippet:', content.substring(0, 200) + '...'); // Log start for debugging
    return null; // Skip invalid
  }
}

// Main logic: Extract the raw array from input (flexible handling)
let rawArray = [];
if (items.length === 1 && Array.isArray(items[0].json)) {
  // Case: Single item with the array inside json (common for API responses)
  rawArray = items[0].json;
  console.log('Detected single item with array inside json. Length:', rawArray.length);
} else if (items.length > 0) {
  // Case: Multiple items, each with json being one object
  rawArray = items.map(item => item.json).filter(Boolean);
  console.log('Detected multiple items. Length:', rawArray.length);
} else {
  console.log('No input items found.');
  return []; // Empty output if no data
}

// Process each object in the rawArray
const cleanedItems = [];
for (const rawItem of rawArray) {
  const content = rawItem?.choices?.[0]?.message?.content;
  if (content) {
    console.log('Processing content for item ID:', rawItem.id); // Debug log
    const cleaned = cleanAndParseContent(content);
    if (cleaned) {
      cleanedItems.push({ json: cleaned });
    } else {
      console.log('Skipping invalid content for item ID:', rawItem.id);
    }
  } else {
    console.log('No content found in item:', rawItem?.id || 'unknown');
  }
}

// Output the cleaned array of items
console.log('Total cleaned items:', cleanedItems.length);
return cleanedItems;

